using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace HdrPilot {
public static class ReShadeGroups {
 public static string QuickHelp {get{return RenoNr.T("1. Installa ReShade. 2. Installa Neural Rendering: add-on e DLL NR per la GPU vengono installati insieme. Gli altri add-on sono opzionali.","1. Install ReShade. 2. Install Neural Rendering: the add-on and GPU-specific NR DLL are installed together. Other add-ons are optional.","1. Instala ReShade. 2. Instala Neural Rendering con la DLL para tu GPU. Otros complementos son opcionales.","1. Installez ReShade. 2. Installez Neural Rendering avec la DLL adaptée au GPU. Autres extensions facultatives.","1. ReShade installieren. 2. Neural Rendering mit passender GPU-DLL installieren. Andere Add-ons sind optional.","1. Instale ReShade. 2. Instale Neural Rendering com a DLL da GPU. Outros complementos são opcionais.");}}

 public static string Help {get{return QuickHelp;}}
 public static string FrameworkHelp {get{return RenoNr.T(
 "REFramework carica mod e script nei giochi RE Engine supportati. Non è obbligatorio per ogni effetto ReShade: installalo quando la mod lo richiede. HDLSS riconosce l’eseguibile e propone il pacchetto ufficiale compatibile. La nightly attuale usa una DLL unica che identifica il gioco; per RE2/RE3/RE7 senza ray tracing scegli la specifica edizione legacy. È installata solo dinput8.dll, senza VR. Script e impostazioni sono conservati. Una dinput8.dll di un altro loader blocca l’installazione. Rimuovi REFramework elimina il loader con copia di recupero: le mod che ne dipendono smetteranno di caricarsi. La compatibilità con patch e demo va verificata nel gioco.",
 "REFramework loads mods and scripts in supported RE Engine games. Not every ReShade effect needs it: install it when required by the mod. HDLSS recognizes the executable and selects the compatible official package. The current nightly uses one DLL that identifies the game; for non-ray-tracing RE2/RE3/RE7 choose the matching legacy edition. Only dinput8.dll is installed, without VR. Scripts and settings are preserved. A different loader using dinput8.dll blocks installation. Remove REFramework deletes the loader with a recovery copy; dependent mods stop loading. Verify compatibility with game patches and demos in game.",
 "REFramework carga mods y scripts en juegos RE Engine compatibles. No es necesario para todos los efectos ReShade. HDLSS reconoce el ejecutable: nightly unificada para juegos actuales, paquete legacy específico para RE2/RE3/RE7 sin ray tracing. Solo instala dinput8.dll, sin VR; conserva scripts y ajustes. Otro cargador en dinput8.dll bloquea la instalación. Eliminar crea una copia de recuperación; las mods dependientes dejan de cargar. Comprueba la compatibilidad con parches y demos.",
 "REFramework charge mods et scripts dans les jeux RE Engine compatibles. Tous les effets ReShade ne l’exigent pas. HDLSS reconnaît l’exécutable : nightly unifiée pour les jeux actuels, paquet legacy adapté à RE2/RE3/RE7 sans ray tracing. Installe seulement dinput8.dll, sans VR, conserve scripts et paramètres. Un autre chargeur dinput8.dll bloque l’installation. La suppression crée une copie de récupération ; les mods dépendants ne chargent plus. Vérifiez les patchs et démos en jeu.",
 "REFramework lädt Mods und Skripte in unterstützten RE-Engine-Spielen. Nicht jeder ReShade-Effekt benötigt es. HDLSS erkennt die Programmdatei: einheitliche Nightly für aktuelle Spiele, passendes Legacy-Paket für RE2/RE3/RE7 ohne Raytracing. Nur dinput8.dll wird installiert, ohne VR; Skripte und Einstellungen bleiben erhalten. Ein anderer dinput8.dll-Loader blockiert die Installation. Entfernen erstellt eine Wiederherstellungskopie; abhängige Mods laden nicht mehr. Kompatibilität mit Patches und Demos im Spiel prüfen.",
 "REFramework carrega mods e scripts em jogos RE Engine compatíveis. Nem todos os efeitos ReShade precisam dele. HDLSS reconhece o executável: nightly unificada para jogos atuais, pacote legacy específico para RE2/RE3/RE7 sem ray tracing. Instala apenas dinput8.dll, sem VR; preserva scripts e definições. Outro loader dinput8.dll bloqueia a instalação. Remover cria cópia de recuperação; mods dependentes deixam de carregar. Verifique compatibilidade com patches e demos.");}}
 public static string SimpleLog {get{return RenoNr.T("Interfaccia semplificata: comandi dei componenti sempre visibili, nessun menu da aprire per installare. Pulsanti compatti allineati a sinistra; descrizioni e importazione in Dettagli.","Simplified interface: component actions always visible, no menu needed to install. Compact left-aligned buttons; descriptions and import in Details.","Interfaz simplificada: acciones siempre visibles, sin abrir menús para instalar. Botones compactos a la izquierda; ayuda e importación en Detalles.","Interface simplifiée : actions toujours visibles sans ouvrir de menu. Boutons compacts à gauche ; aide et importation dans Détails.","Vereinfachte Oberfläche: Aktionen immer sichtbar, kein Menü zum Installieren nötig. Kompakte linksbündige Schaltflächen; Hilfe und Import unter Details.","Interface simplificada: ações sempre visíveis, sem abrir menus para instalar. Botões compactos à esquerda; ajuda e importação em Detalhes.");}}
 public static string ChangeLog {get{return RenoNr.T("9 ottobre · HDR e mod unificata in DLSS 5 · ReShade. Riquadri separati con installazione, aggiornamenti mirati e rimozione. Aggiunto REFramework: riconoscimento eseguibili RE Engine, nightly ufficiale unificata, scelta legacy RE2/RE3/RE7, verifica SHA256 e protezione dei loader esistenti. Guida e sei lingue aggiornate.","9 October · HDR and mods merged into DLSS 5 · ReShade. Separate cards with installation, targeted updates and removal. Added REFramework: RE Engine executable detection, official unified nightly, legacy RE2/RE3/RE7 selection, SHA256 checks and existing loader protection. Guide and six languages updated.","9 octubre · HDR y mods integrada en DLSS 5 · ReShade. Secciones con instalación, actualización individual y eliminación. REFramework con detección de juegos, nightly oficial, legacy RE2/3/7, SHA256 y protección de cargadores. Guía y seis idiomas actualizados.","9 octobre · HDR et mods intégrée à DLSS 5 · ReShade. Sections avec installation, mise à jour ciblée et suppression. REFramework avec détection des jeux, nightly officielle, legacy RE2/3/7, SHA256 et protection des chargeurs. Guide et six langues actualisés.","9. Oktober · HDR und Mods in DLSS 5 · ReShade integriert. Bereiche mit Installation, gezieltem Update und Entfernen. REFramework mit Spielerkennung, offizieller Nightly, Legacy RE2/3/7, SHA256 und Loaderschutz. Hilfe und sechs Sprachen aktualisiert.","9 outubro · HDR e mods integrada em DLSS 5 · ReShade. Secções com instalação, atualização individual e remoção. REFramework com deteção de jogos, nightly oficial, legacy RE2/3/7, SHA256 e proteção de loaders. Guia e seis idiomas atualizados.");}}
 public static void Move(Panel target,UIElement element){var parent=LogicalTreeHelper.GetParent(element) as Panel;if(parent!=null)parent.Children.Remove(element);target.Children.Add(element);}
 public static StackPanel Card(Panel host,string key,string title){var content=new StackPanel();var label=Dialogs.Text(Appearance.Localize(title),17);label.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));label.Margin=new Thickness(0,0,0,10);content.Children.Add(label);var box=LayoutCards.Box(content);box.Tag=key;host.Children.Add(box);return content;}
 static StackPanel Advanced(StackPanel card){var content=new StackPanel();card.Children.Add(new Expander{Header=Appearance.Localize("Details"),Content=content,Margin=new Thickness(0,8,0,0)});return content;}
 static FrameworkElement CompactManagement(Window owner,Game game,string scope,Action refresh){var p=(StackPanel)ModCenter.Panel(owner,game,false,refresh,null,scope);foreach(var t in p.Children.OfType<TextBlock>().ToArray())if(t.Text==Appearance.Localize("Removal"))p.Children.Remove(t);foreach(var dock in p.Children.OfType<DockPanel>())foreach(var t in dock.Children.OfType<TextBlock>().ToArray())dock.Children.Remove(t);return p;}
 static void SizeButtons(DependencyObject element){var panel=element as Panel;if(panel!=null)foreach(UIElement c in panel.Children)SizeButtons(c);var border=element as Border;if(border!=null&&border.Child!=null)SizeButtons(border.Child);var exp=element as Expander;if(exp!=null&&exp.Content is DependencyObject)SizeButtons((DependencyObject)exp.Content);var text=element as TextBlock;if(text!=null){text.Margin=new Thickness(0,3,0,6);var style=new Style(typeof(TextBlock),text.Style);style.Triggers.Add(new Trigger{Property=TextBlock.TextProperty,Value="",Setters={new Setter(UIElement.VisibilityProperty,Visibility.Collapsed)}});text.Style=style;}var button=element as Button;if(button!=null){button.HorizontalAlignment=HorizontalAlignment.Left;button.HorizontalContentAlignment=HorizontalAlignment.Left;button.MinWidth=90;}}
 public static FrameworkElement Build(Window owner,Game game,WrapPanel actions,StackPanel details,WrapPanel channels,ComboBox menu,Button map,FrameworkElement asi,TextBlock info,Action<DlssPlan> review,Action refresh){var root=new StackPanel();root.Children.Add(Dialogs.Text(QuickHelp,14));Move(root,info);var grid=new Grid();root.Children.Add(grid);Action arrange=()=>{int columns=grid.ActualWidth>=1100?2:1;grid.ColumnDefinitions.Clear();for(int n=0;n<columns;n++)grid.ColumnDefinitions.Add(new ColumnDefinition());grid.RowDefinitions.Clear();int count=grid.Children.Count;for(int n=0;n<(count+columns-1)/columns;n++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});for(int n=0;n<count;n++){Grid.SetRow(grid.Children[n],n/columns);Grid.SetColumn(grid.Children[n],n%columns);}};int lastColumns=0;grid.SizeChanged+=(s,e)=>{int columns=grid.ActualWidth>=1100?2:1;if(columns!=lastColumns){lastColumns=columns;arrange();}};
 var re=Card(grid,"reshade","ReShade");var hdr=Card(grid,"hdr","RenoDX HDR");var nr=Card(grid,"nr","DLSS 5 · Neural Rendering");var mfg=Card(grid,"mfg","MFG Unlock");var shaders=Card(grid,"effects",Appearance.Localize("Add-on e shader ReShade"));
 var reAdvanced=Advanced(re);Move(reAdvanced,channels);reAdvanced.Children.Add(Dialogs.Text(Appearance.Localize("Tasto overlay ReShade · senza modificatori"),14));Move(reAdvanced,menu);Move(reAdvanced,map);var hdrAdvanced=Advanced(hdr);var mfgAdvanced=Advanced(mfg);
 foreach(var b in actions.Children.OfType<Button>().Concat(details.Children.OfType<Button>()).ToArray()){string tag=Convert.ToString(b.Tag);if(tag=="Installa ReShade selezionato")Move(re,b);else if(tag=="Importa pacchetto ReShade…")Move(reAdvanced,b);else if(tag=="Installa / aggiorna RenoDX"){b.Content=Appearance.Localize("Installa RenoDX");Move(hdr,b);}else if(tag=="Importa mod RenoDX locale…"||tag=="Catalogo mod RenoDX")Move(hdrAdvanced,b);else if(tag=="Install MFG Unlock")Move(mfg,b);else if(tag=="MFG Unlock · compatibility")Move(mfgAdvanced,b);}
 foreach(var pair in new[]{new{Panel=re,Scope="reshade"},new{Panel=hdr,Scope="renodx"},new{Panel=mfg,Scope="mfg"}})pair.Panel.Children.Add(CompactManagement(owner,game,pair.Scope,refresh));
 var nrBody=(StackPanel)RenoNr.Panel(owner,game,refresh,false);var nrAdvanced=Advanced(nr);foreach(var child in nrBody.Children.Cast<UIElement>().ToArray()){var text=child as TextBlock;var exp=child as Expander;if(exp!=null){if(exp.Content is UIElement){var c=(UIElement)exp.Content;exp.Content=null;nrAdvanced.Children.Add(c);}nrBody.Children.Remove(exp);}else if(text!=null&&(text.Text==RenoNr.Intro||text.Text==RenoNr.Policy))nrBody.Children.Remove(child);}nr.Children.Insert(1,nrBody);foreach(var row in nrBody.Children.OfType<Panel>())foreach(var button in row.Children.OfType<Button>().ToArray())if(button.Style==owner.TryFindResource("InfoAction")||Convert.ToString(button.Content)==RenoNr.T("Apri download RenoDX","Open RenoDX downloads","Abrir descargas RenoDX","Ouvrir les téléchargements RenoDX","RenoDX-Downloads öffnen","Abrir downloads RenoDX"))Move(nrAdvanced,button);
 shaders.Children.Add(EffectCatalog.Panel(game,owner,review,info));shaders.Children.Add(CompactManagement(owner,game,"effect",refresh));
 if(ReFramework.Identify(game)!=null)Card(grid,"reframework","REFramework · RE Engine").Children.Add(ReFramework.Panel(owner,game));
 var loader=Card(grid,"asi","ASI Loader");asi.Visibility=Visibility.Visible;Move(loader,asi);loader.Children.Add(CompactManagement(owner,game,"asi",refresh));
 if(ReFramework.Identify(game)==null&&(game.Confirmed||(game.EngineLabel??"").StartsWith("UNREAL")||ModInventory.Scan(game).Any(i=>i.Id=="ue4ss"))){var ue=Card(grid,"ue4ss","UE4SS");foreach(var b in details.Children.OfType<Button>().Where(b=>Convert.ToString(b.Tag)=="Install UE4SS for mods").ToArray())Move(ue,b);ue.Children.Add(CompactManagement(owner,game,"ue4ss",refresh));}
 if(ModInventory.Scan(game).Any(i=>i.Id=="addon"&&!RenoNr.Detected(game).Contains(i.File,StringComparer.OrdinalIgnoreCase)))Card(grid,"other","Other ReShade add-ons").Children.Add(CompactManagement(owner,game,"addon",refresh));
 foreach(var card in grid.Children.OfType<Border>()){var p=(StackPanel)card.Child;foreach(var exp in p.Children.OfType<Expander>().ToArray()){p.Children.Remove(exp);p.Children.Add(exp);}}
 var cards=grid.Children.Cast<Border>().ToArray();grid.Children.Clear();root.Children.Remove(grid);
 foreach(var card in cards){var title=((StackPanel)card.Child).Children.OfType<TextBlock>().First();if((string)card.Tag=="reshade")title.Text="1. "+Appearance.Localize("Install ReShade");if((string)card.Tag=="nr")title.Text="2. "+RenoNr.T("Installa Neural Rendering","Install Neural Rendering","Instalar Neural Rendering","Installer Neural Rendering","Neural Rendering installieren","Instalar Neural Rendering");}
 root.Children.Add(LayoutCards.GridFor(cards.Where(c=>(string)c.Tag=="reshade"||(string)c.Tag=="nr").Cast<UIElement>().ToArray()));
 root.Children.Add(new Expander{Header=RenoNr.T("Add-on opzionali · RenoDX HDR, MFG e shader","Optional add-ons · RenoDX HDR, MFG and shaders","Complementos opcionales · RenoDX HDR, MFG y shaders","Extensions facultatives · RenoDX HDR, MFG et shaders","Optionale Add-ons · RenoDX HDR, MFG und Shader","Complementos opcionais · RenoDX HDR, MFG e shaders"),Content=LayoutCards.GridFor(cards.Where(c=>new[]{"hdr","mfg","effects","other"}.Contains((string)c.Tag)).Cast<UIElement>().ToArray()),Margin=new Thickness(0,12,0,0)});
 root.Children.Add(new Expander{Header=RenoNr.T("Loader per altre mod · avanzato","Loaders for other mods · advanced","Cargadores para otras mods · avanzado","Chargeurs pour autres mods · avancé","Loader für andere Mods · erweitert","Loaders para outras mods · avançado"),Content=LayoutCards.GridFor(cards.Where(c=>new[]{"asi","reframework","ue4ss"}.Contains((string)c.Tag)).Cast<UIElement>().ToArray()),Margin=new Thickness(0,12,0,0)});
 LayoutCards.Style(root);return root;
 }
}
